<script setup lang="ts">
import { computed, ref } from "vue"; import { http } from "@/utils/http";
type Job = Record<string, any>; const rows = ref<Job[]>([]); const loading = ref(false); const error = ref(""); const status = ref(""); const query = ref(""); const enabled = ref(""); const subsystem = ref(""); const scheduleType = ref(""); const lastResult = ref(""); const detail = ref<any>(false); const counts = computed(() => ({ running: rows.value.filter(row => String(row.status).toUpperCase() === 'RUNNING').length, queued: rows.value.filter(row => String(row.status).toUpperCase() === 'QUEUED').length, failed: rows.value.filter(row => String(row.status).toUpperCase() === 'FAILED').length })); const filtered = computed(() => rows.value.filter(row => (!query.value || JSON.stringify(row).toLowerCase().includes(query.value.toLowerCase())) && (!status.value || String(row.status).toUpperCase() === status.value) && (!enabled.value || String(Boolean(row.enabled)) === enabled.value) && (!subsystem.value || row.subsystem === subsystem.value) && (!scheduleType.value || row.scheduleType === scheduleType.value) && (!lastResult.value || row.lastResult === lastResult.value)));
async function load() { loading.value = true; try { const result: any = await http.get("/background-tasks"); const values = Array.isArray(result) ? result : (result?.content || result?.items || []); rows.value = values; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "运维任务加载失败"; } finally { loading.value = false; } } load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">定时任务与运维作业</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">查看作业状态、进度和最近运行结果。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><div class="grid grid-cols-1 md:grid-cols-4 gap-4 mb-5"><el-card shadow="never"><div class="text-sm">运行中</div><div class="text-2xl font-semibold mt-2">{{ counts.running }}</div></el-card><el-card shadow="never"><div class="text-sm">排队中</div><div class="text-2xl font-semibold mt-2">{{ counts.queued }}</div></el-card><el-card shadow="never"><div class="text-sm">最近失败</div><div class="text-2xl font-semibold mt-2">{{ counts.failed }}</div></el-card><el-card shadow="never"><div class="text-sm">最近完成</div><div class="text-2xl font-semibold mt-2">{{ rows.length - counts.running - counts.queued - counts.failed }}</div></el-card></div><div class="flex flex-wrap gap-3 mb-4"><el-input v-model="query" clearable placeholder="搜索 Job ID / 名称" class="w-56"/><el-select v-model="enabled" clearable placeholder="Enabled"><el-option label="已启用" value="true"/><el-option label="已禁用" value="false"/></el-select><el-select v-model="status" clearable placeholder="Status"><el-option label="运行中" value="RUNNING"/><el-option label="排队中" value="QUEUED"/><el-option label="失败" value="FAILED"/><el-option label="成功" value="COMPLETED"/></el-select><el-input v-model="subsystem" clearable placeholder="Subsystem" class="w-36"/><el-select v-model="scheduleType" clearable placeholder="Schedule Type"><el-option label="Cron" value="CRON"/><el-option label="Interval" value="INTERVAL"/></el-select><el-select v-model="lastResult" clearable placeholder="Last Result"><el-option label="成功" value="SUCCESS"/><el-option label="失败" value="FAILED"/></el-select></div><el-skeleton v-if="loading" :rows="8" animated/><el-card v-else shadow="never"><el-empty v-if="!filtered.length" description="暂无运维作业"/><el-table v-else :data="filtered" stripe><el-table-column prop="enabled" label="Enabled" width="90"/><el-table-column prop="name" label="Job Name" min-width="200"><template #default="{ row }">{{ row.name || row.type || row.id }}</template></el-table-column><el-table-column prop="subsystem" label="Owning Subsystem" width="150"/><el-table-column prop="scheduleSummary" label="Schedule / Cron" min-width="180"/><el-table-column prop="nextRun" label="Next Run" min-width="180"/><el-table-column prop="lastRun" label="Last Run" min-width="180"/><el-table-column prop="lastResult" label="Last Result" width="130"/><el-table-column prop="lastDuration" label="Last Duration" width="130"/><el-table-column prop="concurrencyPolicy" label="Concurrency" width="130"/><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link @click="detail = row">详情</el-button></template></el-table-column></el-table></el-card><el-drawer v-model="detail" title="作业详情" size="520px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="Job ID">{{ detail.id }}</el-descriptions-item><el-descriptions-item label="描述">{{ detail.description || '—' }}</el-descriptions-item><el-descriptions-item label="所属子系统">{{ detail.subsystem || '—' }}</el-descriptions-item><el-descriptions-item label="Schedule Expression">{{ detail.scheduleExpression || detail.scheduleSummary || '—' }}</el-descriptions-item><el-descriptions-item label="Timezone">{{ detail.timezone || '—' }}</el-descriptions-item><el-descriptions-item label="Concurrency / Misfire">{{ detail.concurrencyPolicy || '—' }} / {{ detail.misfirePolicy || '—' }}</el-descriptions-item><el-descriptions-item label="Retry Policy">{{ detail.retryPolicy || '—' }}</el-descriptions-item></el-descriptions><el-alert title="立即运行需遵循后端并发策略，不能静默启动重复实例。" type="info" show-icon class="mt-4"/></el-drawer></main></template>
